/** Finds a bundled brand icon whose keyword appears in (or contains) the label, case-insensitive. */
export function suggestIcon(label: string): string | null {
  const norm = label.toLowerCase().replace(/\s+/g, '')
  if (!norm) return null
  for (const entry of ICON_SUGGESTIONS) {
    for (const kw of entry.keywords) {
      if (norm.includes(kw)) return entry.icon
    }
  }
  return null
}
